            && let Some(handle) = self.column_scroll.get(key)
            && handle.max_offset().y > px(0.)
        {
            let speed = edge_speed(at.y, cards.top(), cards.bottom());
            held |= speed != 0.;
            moved |= scroll_by(handle, Axis::Vertical, px(speed * ms));
