/// The gap a story named `dragged`, with the pointer `at`, would land in:
/// among the cards of the column the pointer is over, before the first
/// whose middle is below it, else after the last, and none in a column
/// that takes no drops, nor either side of the story itself. `columns` are
/// those that take drops, each with its stories' names in order.
fn choose_gap(
    dragged: &str,
    at: Point<Pixels>,
    columns: &[(Section, Vec<String>)],
    column_bounds: &ColumnBounds,
    row_bounds: &std::collections::HashMap<String, Bounds<Pixels>>,
) -> Option<(Section, usize)> {
    let (section, names) = columns.iter().find(|(section, _)| {
        column_bounds
            .get(section.key())
            .is_some_and(|(column, _)| column.contains(&at))
    })?;
    let gap = names
        .iter()
        .position(|name| {
            row_bounds
                .get(name)
                .is_some_and(|row| row.center().y > at.y)
        })
        .unwrap_or(names.len());
    match names.iter().position(|name| name == dragged) {
        Some(from) if gap == from || gap == from + 1 => None,
        _ => Some((*section, gap)),
    }
