            gap: Rc::default(),
            dragged: Rc::default(),
            column_bounds: Rc::default(),
            board_bounds: Rc::default(),
            drag_scrolling: false,
            writes: Arc::default(),
            _tick: None,
            advancing: false,
            waiting_start: false,
            left_empty: 0,
            loaded: false,
            load_error: None,
            save_waiting: Cell::new(false),
            save_error: Arc::default(),
            pause_focus: cx.focus_handle().tab_stop(true),
            panel_focus: cx.focus_handle(),
