fn render_column(
    &self,
    key: &'static str,
    heading: AnyElement,
    cards: Vec<AnyElement>,
    cx: &mut Context<Self>,
) -> AnyElement {
    let handle = self.column_scroll[key].clone();
    let overflows = handle.max_offset().y > px(0.);
    // The cards its own children, so it can be scrolled to any of them.
    let body = v_flex()
        .id(SharedString::from(format!("planning-column-{key}-cards")))
        .size_full()
        .overflow_y_scroll()
        .track_scroll(&handle)
        .gap(CARD_GAP)
        .children(
            cards
                .into_iter()
                .map(|card| div().w_full().flex_none().child(card)),
        );
    let body = if overflows {
        crate::scrollbar::with_scrollbar(
            format!("planning-column-{key}"),
            &handle,
            body,
            true,
            None,
            cx,
        )
    } else {
        body.into_any_element()
    };
    // Once the cards come to hold more than fits, or fit again, the
    // scrollbar is shown, or hidden, from the next frame.
    let this = cx.entity().downgrade();
    let watch = canvas(
        move |_, _, cx| {
            if (handle.max_offset().y > px(0.)) != overflows {
                let this = this.clone();
                cx.defer(move |cx| {
                    this.update(cx, |_, cx| cx.notify()).ok();
                });
            }
        },
        |_, _, _, _| {},
    )
    .absolute()
    .size_0();
    let record = |cards: bool| {
        let columns = self.column_bounds.clone();
        canvas(
            move |bounds, _, _| {
                let mut columns = columns.borrow_mut();
                let at = columns.entry(key).or_insert((bounds, bounds));
                if cards {
                    at.1 = bounds;
                } else {
                    at.0 = bounds;
                }
            },
            |_, _, _, _| {},
        )
        .absolute()
        .top_0()
        .left_0()
        .size_full()
    };
    // A list, as Trello draws one: on the recessed surface, one step
    // from the board's base, its corners rounded, with no border.
    let recessed = crate::theme::color(crate::theme::palette(cx).recessed);
    gpui_kit::TestSupportExt::test_support(
        v_flex()
            .id(SharedString::from(format!("planning-column-{key}")))
            .track_focus(&self.section_focus[key])
            .relative()
            .w(COLUMN_WIDTH)
            .flex_none()
            .h_full()
            .min_h_0()
            .p(LIST_PADDING)
            .rounded(px(8.))
            .bg(recessed)
            .child(record(false))
            .child(div().flex_none().pb(HEADING_GAP).child(heading))
            .child(
                div()
                    .relative()
                    .flex_1()
                    .min_h_0()
                    .w_full()
                    .child(record(true))
                    .child(body),
            )
            .child(watch),
    )
    .into_any_element()
}

/// A section's column: its heading, and its cards.
fn render_section(
    &mut self,
    section: Section,
    window: &mut Window,
    cx: &mut Context<Self>,
) -> AnyElement {
    let theme = cx.theme().clone();
    let muted = theme.muted_foreground;
    let heading = self.render_heading(section, window, cx);
    let mut cards: Vec<AnyElement> = Vec::new();
    // While the plan is read: skeleton cards, never an empty column.
    if !self.loaded {
        if section == Section::Next
            && let Some(why) = self.load_error.clone()
        {
            cards.push(
                gpui_kit::TestSupportExt::test_support(
                    h_flex()
                        .id("planning-load-error")
                        .gap_2()
                        .items_center()
                        .child(div().flex_1().text_sm().text_color(theme.danger).child(why))
                        .child(
                            Button::new("planning-load-retry")
                                .ghost()
                                .xsmall()
                                .label("Try again")
                                .tooltip("Read the plan again")
                                .on_click(cx.listener(|this, _, _, cx| this.read_again(cx))),
                        ),
                )
                .into_any_element(),
            );
        } else {
            cards.push(
                gpui_kit::TestSupportExt::test_support(
                    v_flex()
                        .id(SharedString::from(format!(
                            "planning-loading-{}",
                            section.key()
                        )))
                        .gap(CARD_GAP)
                        .child(skeleton_card(cx))
                        .child(skeleton_card(cx)),
                )
                .into_any_element(),
            );
        }
        return self.render_column(section.key(), heading, cards, cx);
    }
    let gap = self.gap.get();
    let count = self.sections[section_ix(section)].len();
    let takes_drops = matches!(section, Section::Backlog | Section::Next);
    if count == 0 {
        let empty = div().id(SharedString::from(format!(
            "planning-empty-{}",
            section.key()
        )));
        // An empty column that takes drops takes them at its top,
        // its line across it beneath the heading.
        let empty = empty.relative().when(
            takes_drops && gap == Some((section, 0)) && cx.has_active_drag(),
            |empty| empty.child(crate::prompt_mode::drop_indicator(false, false, cx)),
        );
        // Lets UI tests find the empty state; inert in normal builds.
        cards.push(
            gpui_kit::TestSupportExt::test_support(
                empty.child(empty_line(section.empty(), muted)),
            )
            .into_any_element(),
        );
    }
    for ix in 0..count {
        let name = self.sections[section_ix(section)][ix].name.clone();
        let open = self.open.as_ref().is_some_and(|open| open.name == name);
        cards.push(self.render_row(section, ix, open, gap, window, cx));
    }
    // The composer, where its story will sit, the cards below it moved
    // down, and the list scrolled to keep it in view.
    let composing = self
        .composer
        .as_ref()
        .filter(|composer| composer.section == section)
        .map(|composer| composer.at.min(count));
    if let Some(at) = composing {
        // With no cards, in the line's place, beneath the empty state.
        let at = if count == 0 { cards.len() } else { at };
        cards.insert(at, self.render_composer(cx));
        if let Some(composer) = self.composer.as_mut().filter(|composer| composer.reveal) {
            composer.reveal = false;
            self.column_scroll[section.key()].scroll_to_item(at);
        }
    }
    // The "Add story" line at its foot, after its last card.
    if takes_drops && composing.is_none_or(|at| at < count) {
        cards.push(self.render_add_line(section, window, cx));
    }
    self.render_column(section.key(), heading, cards, cx)
}

