            .child(
                h_flex()
                    .size_full()
                    .min_h_0()
                    .child(
                        v_flex().flex_1().min_w_0().h_full().children(bars).child(
                            div()
                                .relative()
                                .flex_1()
                                .min_h_0()
                                .w_full()
                                .child(board)
                                .child(board_frame),
